try (var pool = Executors.newFixedThreadPool(n)) {
    var cs = new ExecutorCompletionService<Long>(pool);
    parts.forEach(p -> cs.submit(() -> partialSum(p)));
    long total = 0;
    for (int i = 0; i < parts.size(); i++) total += cs.take().get();
    return total;
}

