var pool = Executors.newFixedThreadPool(n);
var futures = parts.stream()
    .map(p -> CompletableFuture.supplyAsync(() -> partialSum(p), pool))
    .toList();
long total = futures.stream().mapToLong(CompletableFuture::join).sum();
pool.shutdown();

try (var exec = Executors.newVirtualThreadPerTaskExecutor()) {
    var futures = parts.stream()
        .map(p -> exec.submit(() -> partialSum(p)))
        .toList();
    long total = 0;
    for (var f : futures) total += f.get();
    return total;
}
